package com.vandorlabs.neoforge.ramp;
import java.util.UUID;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.Block;
/** Actual installed/pending chunk markers, worker/cold refusal and warmed lookup costs. */
final class NativeRampPartOwnershipChecks {
 static int serializations;
 static void run(ServerLevel level,BlockPos pos,Block block,UUID operation,BlockPos root){var original=level.getBlockEntity(pos);var saved=original.saveWithFullMetadata(level.registryAccess());var trace=new NativeRampPartOwnership.Trace();NativeRampPartOwnership.trace=trace;
  try{
   need(NativeRampPartOwnership.read(level,pos,block,operation,root)==NativeRampPartOwnership.State.OWNED,"live owned marker");need(NativeRampPartOwnership.read(level,pos,block,new UUID(0,938),root)==NativeRampPartOwnership.State.OTHER,"different operation remains another owner");
   warm(level,pos,block,operation,root,trace,false);
   level.removeBlockEntity(pos);var chunk=level.getChunkSource().getChunkNow(pos.getX()>>4,pos.getZ()>>4);chunk.setBlockEntityNbt(saved.copy());need(NativeRampPartOwnership.read(level,pos,block,operation,root)==NativeRampPartOwnership.State.OWNED&&chunk.getBlockEntities().get(pos)==null,"pending raw marker without factory initialization");warm(level,pos,block,operation,root,trace,true);
   var malformed=saved.copy();malformed.putIntArray("Operation",new int[]{1,2,3});chunk.setBlockEntityNbt(malformed);need(NativeRampPartOwnership.read(level,pos,block,operation,root)==NativeRampPartOwnership.State.UNKNOWN&&chunk.getBlockEntities().get(pos)==null,"malformed pending marker stays unknown without decode");var wrong=saved.copy();wrong.putString("RootX","future");var detached=new NativeRampJournalPart(original.getType(),pos,original.getBlockState());detached.loadWithComponents(wrong,level.registryAccess());need(!detached.ownershipKnown()&&detached.saveWithFullMetadata(level.registryAccess()).equals(wrong),"malformed native root coordinates retain exact inert snapshot");var future=saved.copy();future.putInt("NativeRampPartSchema",99);chunk.setBlockEntityNbt(future);need(NativeRampPartOwnership.read(level,pos,block,operation,root)==NativeRampPartOwnership.State.UNKNOWN,"future marker stays unknown");chunk.setBlockEntityNbt(saved.copy());need(level.getBlockEntity(pos) instanceof NativeRampJournalPart part&&part.belongs(operation,root),"restored pending factory retains exact ownership");
   var cold=new BlockPos(399999,root.getY(),399999);need(level.getChunkSource().getChunkNow(cold.getX()>>4,cold.getZ()>>4)==null,"cold marker precondition");trace.clear();need(NativeRampPartOwnership.read(level,cold,block,operation,root)==NativeRampPartOwnership.State.COLD&&trace.chunks==1&&trace.states==0&&level.getChunkSource().getChunkNow(cold.getX()>>4,cold.getZ()>>4)==null,"cold lookup does not load or inspect state");trace.clear();need(java.util.concurrent.CompletableFuture.supplyAsync(()->NativeRampPartOwnership.read(level,pos,block,operation,root)).join()==NativeRampPartOwnership.State.UNKNOWN&&trace.chunks==0,"worker refuses before chunk access");
   System.out.println("[vandorlabs][ramp-part-ownership] PASS live/pending/unknown/cold/worker and zero serialization");
  }finally{NativeRampPartOwnership.trace=null;}
 }
 private static void warm(ServerLevel level,BlockPos pos,Block block,UUID operation,BlockPos root,NativeRampPartOwnership.Trace trace,boolean pending){for(int i=0;i<20000;i++)NativeRampPartOwnership.read(level,pos,block,operation,root);var bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();bean.setThreadAllocatedMemoryEnabled(true);long id=Thread.currentThread().threadId();var bytes=new long[3];for(int batch=0;batch<3;batch++){trace.clear();int beforeSerializations=serializations;long before=bean.getThreadAllocatedBytes(id);for(int i=0;i<10000;i++)if(NativeRampPartOwnership.read(level,pos,block,operation,root)!=NativeRampPartOwnership.State.OWNED)throw new AssertionError("Lost warm owner");bytes[batch]=bean.getThreadAllocatedBytes(id)-before;need(bytes[batch]<=64&&serializations==beforeSerializations&&trace.chunks==10000&&trace.states==10000&&trace.live==10000&&trace.pending==(pending?10000:0),"bounded warm lookup allocations/reads batch="+batch+" bytes="+bytes[batch]);}System.out.println("[vandorlabs][ramp-part-ownership] warm "+(pending?"pending":"live")+" bytes="+java.util.Arrays.toString(bytes)+" per10000; chunk/state/map reads1 each, full saves0");}
 private static void need(boolean ok,String text){if(!ok)throw new AssertionError("Ramp marker lookup: "+text);}
}
